    }
    // 草稿按轮次序号定位，序号从锁里现读（写类围栏已在分发处核过代数与锁，这里读到的必是本轮的锁）。
    const lock = await readLock(root);
    if (lock === null) {
      throw new CliError('锁已不存在，没法收尾——这轮多半已被接管或已经收过尾', EXIT.STALE_GENERATION);
    }
    const seq = lock.tick_seq;
    if (!Number.isInteger(seq) || seq <= 0) {
      throw new CliError('锁文件里的轮次序号不像话，没法把收尾字段落进草稿');
    }
    const rel = WRITE_TYPES['tick-field'].path(seq);
    const existing = (await readJson(root, rel)) ?? {};
    await writeJson(root, rel, { ...existing, ...fields }, { actor: '主控', event: 'write:tick-field' });
  }

  const result = await tickEnd(root, {
    generation,
    status: data.status,
    action: typeof data.action === 'string' ? data.action : null
  });
  process.stdout.write(result.markdown); // 汇报当场打印给触发者，最后一行照旧是 JSON 结果
  return {
    output: { ok: true, tick: result.seq, status: result.status, report: result.reportRel, released: true },
    exit: result.exit
  };
}

// status 子命令：一屏中文看盘快照（阶段/控制位/里程碑树/当前 sprint/待拍板/四级账/最近汇报）。
// 纯读不写、秒回；熔断态也照常出快照（看盘不是闸门），并附两条出路指引。
// 人读的快照直接打到 stdout，机器读的结构化摘要照返回契约走末尾那行 JSON。
async function cmdStatus({ root }) {
  const { text, data } = await statusSnapshot(root);
  process.stdout.write(text + '\n');
  return { output: { ok: true, ...data }, exit: EXIT.OK };
}

// audit 子命令：事后追溯时间线，一轮一行「第N轮｜谁｜干了什么｜依据｜花费｜耗时」。
// 用法：audit [--milestone 编号] [--from 时刻] [--to 时刻]；纯读不写，stdout 原样打印。
async function cmdAudit({ root, flags }) {
  if (flags.milestone === true) {
    throw new CliError('--milestone 需要带里程碑编号，比如 --milestone M1');
  }
  if (flags.from === true || flags.to === true) {
    throw new CliError('--from / --to 需要带时刻，请用 ISO 格式，比如 2026-07-03T00:00:00Z');
  }
  const { lines, rounds } = await auditTimeline(root, {
    milestone: typeof flags.milestone === 'string' ? flags.milestone : null,
    from: typeof flags.from === 'string' ? flags.from : null,
    to: typeof flags.to === 'string' ? flags.to : null
  });
  if (lines.length > 0) {
    process.stdout.write(lines.join('\n') + '\n');
  }
  return { output: { ok: true, rounds }, exit: EXIT.OK };
}

